#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
source scripts/source_mujoco_setup.sh "${1:-box_75}"
SIM="${HOLOSOMA_MJ_SIMULATOR:-mujoco-split-debug}"
export TRAINING_HEADLESS="${TRAINING_HEADLESS:-False}"
[[ -f "$HOLOSOMA_MJ_MOTION" && -f "$HOLOSOMA_MJ_OBJECT_URDF" && -f "${HOLOSOMA_MJ_OBJECT_URDF%.urdf}.obj" ]] || { echo "missing data_demo files for $HOLOSOMA_MJ_CLIP" >&2; exit 1; }
python -u src/holosoma/holosoma/run_sim.py simulator:"$SIM" robot:g1-29dof-w-object terrain:terrain-locomotion-plane perception:"$PERCEPTION_PRESET" --training.headless "$TRAINING_HEADLESS" --device "$SIM_DEVICE" --robot.init-state.pos "$ROBOT_INIT_STATE_POS" --robot.init-state.rot "$ROBOT_INIT_STATE_ROT" --robot.asset.enable-self-collisions "$ROBOT_ENABLE_SELF_COLLISIONS" --robot.object.enabled True --robot.object.object-urdf-path "$HOLOSOMA_MJ_OBJECT_URDF" --robot.object.mujoco-use-training-urdf-scene "$SIM_USE_TRAINING_URDF_OBJECT_SCENE" --robot.object.mujoco-add-default-actuators "$SIM_ADD_DEFAULT_OBJECT_ACTUATORS" --robot.object.mujoco-copy-joint-defaults-from-robot-xml "$SIM_COPY_JOINT_DEFAULTS_FROM_ROBOT_XML" --robot.object.mujoco-copy-tendons-from-robot-xml "$SIM_COPY_TENDONS_FROM_ROBOT_XML" --robot.object.mujoco-copy-collision-geoms-from-robot-xml "$SIM_COPY_COLLISION_GEOMS_FROM_ROBOT_XML" --robot.object.mujoco-copy-contact-pairs-from-robot-xml "$SIM_COPY_CONTACT_PAIRS_FROM_ROBOT_XML" --robot.object.mujoco-object-mass-override "$HOLOSOMA_MJ_OBJECT_MASS" --motion-init.enabled=True --motion-init.motion-file "$HOLOSOMA_MJ_MOTION" --motion-init.mode "$SIM_MOTION_INIT_MODE" --motion-init.object-name object --simulator.config.debug-viz "$SIM_DEBUG_VIZ" --simulator.config.contact-force-viz "$SIM_CONTACT_FORCE_VIZ" --simulator.config.sim.fps "$SIM_FPS" --simulator.config.sim.control-decimation "$SIM_CONTROL_DECIMATION" --simulator.config.sim.substeps "$SIM_SUBSTEPS" --simulator.config.sim.physx.num-position-iterations "$SIM_PHYSX_POSITION_ITERATIONS" --simulator.config.sim.physx.num-velocity-iterations "$SIM_PHYSX_VELOCITY_ITERATIONS" --simulator.config.sim.physx.bounce-threshold-velocity "$SIM_PHYSX_BOUNCE_THRESHOLD_VELOCITY" --simulator.config.mujoco-backend "$MUJOCO_BACKEND" --simulator.config.virtual-gantry.enabled "$SIM_VIRTUAL_GANTRY_ENABLED" --terrain.terrain-term.static-friction "$TERRAIN_STATIC_FRICTION" --terrain.terrain-term.dynamic-friction "$TERRAIN_DYNAMIC_FRICTION" --simulator.config.bridge.interface "$SIM_BRIDGE_INTERFACE" --simulator.config.bridge.clock-port "$SIM_CLOCK_PORT" --simulator.config.bridge.sim-state-port "$SIM_STATE_PORT" --simulator.config.bridge.publish-sim-state True --simulator.config.bridge.listen-control True --simulator.config.bridge.use-zmq-lowcmd True --simulator.config.bridge.ignore-default-idle-command True --simulator.config.bridge.freeze-until-first-command True --simulator.config.bridge.publish-perception-obs True --simulator.config.bridge.perception-obs-port "$PERCEPTION_OBS_PORT" --simulator.config.bridge.publish-perception-obs-shm True --simulator.config.bridge.control-port "$SIM_CONTROL_PORT" --simulator.config.bridge.perception-obs-shm-name "$PERCEPTION_OBS_SHM_NAME" --perception.camera-source "$PERCEPTION_CAMERA_SOURCE" --perception.object-geometry-mode "$PERCEPTION_OBJECT_GEOMETRY_MODE" --perception.camera-pitch-deg "$PERCEPTION_CAMERA_PITCH_DEG" --perception.camera-warp-edge-noise "$PERCEPTION_CAMERA_WARP_EDGE_NOISE" --perception.camera-warp-enable-holes "$PERCEPTION_CAMERA_WARP_ENABLE_HOLES" --perception.camera-apply-sensor-noise "$PERCEPTION_CAMERA_APPLY_SENSOR_NOISE"
